class Solution {
public:
    int mostFrequentEven(std::vector<int>& nums) {
        std::unordered_map<int, int> counts;
        for (int x : nums) {
            if (x % 2 == 0) counts[x]++;
        }
        if (counts.empty()) return -1;
        int best_val = -1, best_freq = 0;
        for (const auto& [val, freq] : counts) {
            if (freq > best_freq || (freq == best_freq && (best_val == -1 || val < best_val))) {
                best_freq = freq;
                best_val = val;
            }
        }
        return best_val;
    }
};

class Solution {
    public int mostFrequentEven(int[] nums) {
        java.util.Map<Integer, Integer> counts = new java.util.HashMap<>();
        for (int x : nums) {
            if (x % 2 == 0) counts.put(x, counts.getOrDefault(x, 0) + 1);
        }
        if (counts.isEmpty()) return -1;
        int bestVal = -1, bestFreq = 0;
        for (var entry : counts.entrySet()) {
            int val = entry.getKey(), freq = entry.getValue();
            if (freq > bestFreq || (freq == bestFreq && (bestVal == -1 || val < bestVal))) {
                bestFreq = freq;
                bestVal = val;
            }
        }
        return bestVal;
    }
}

var mostFrequentEven = function(nums) {
    const counts = new Map();
    for (const x of nums) {
        if (x % 2 === 0) {
            counts.set(x, (counts.get(x) || 0) + 1);
        }
    }
    if (counts.size === 0) return -1;
    let bestVal = -1, bestFreq = 0;
    for (const [val, freq] of counts.entries()) {
        if (freq > bestFreq || (freq === bestFreq && (bestVal === -1 || val < bestVal))) {
            bestFreq = freq;
            bestVal = val;
        }
    }
    return bestVal;
};
